2	###### AirArcanaCountItem AirArcanaCountItem.cs
3	SPEC: | Р-181 | `wind_roster_dash_boon` | амулет: бесплатный рывок и уклонение по числу воздушных арканов | Защита | DASH, COND | Считает открытые (открытые) арканы воздушной стихии у игрока на момент активации (N). При входе в базовый рывок бросает две независимые проверки. (1) Шанс уклонения на время рывка = 10% + 2.5% × N: на рывок вешается +1 к стату уклонения, снимается при выходе из рывка (рисуется эффект ветра). (2) Шанс «бесплатного рывка» = 1.2% + 0.8% × N: у рывка отключается стартовая перезарядка и перезарядка сразу готова. Счёт N не пересчитывается при открытии арканов после активации. | т2 / 6 | — | часть группы Г11 «счёт арканов стихии» | Источник: AirArcanaCountItem (база EleArcanaUnlockCountItem → ArcanaCountItem) |
4	public class AirArcanaCountItem : EleArcanaUnlockCountItem
5	{
6		public static string staticID = "AirArcanaCountItem";
7		private Player.BaseDashState dashSkill;
8		private ParticleEffect currentEffect;
9		private NumVarStatMod evadeMod;
10		private bool modApplied;
11		private bool evadeApplied;
12		private float evadeChance;
13		protected override string ExtraInfo => PercentToStr(chanceMod, "+") + " | " + PercentToStr(evadeChance, "+");
14		public AirArcanaCountItem()
15			: base(staticID, ElementType.Air, 0.012f, 0.008f)
16		{
17			category = Category.Defense;
18			evadeMod = new NumVarStatMod(staticID, 1f);
19		}
20		public override bool SetStatus(bool givenStatus)
21		{
22			if (!base.SetStatus(givenStatus))
23			{
24				return false;
25			}
26			Player player = parentPlayer;
27			player.skillEnterEventHandlers = (Player.SkillEventHandler)Delegate.Remove(player.skillEnterEventHandlers, new Player.SkillEventHandler(OnSkillEnter));
28			Player player2 = parentPlayer;
29			player2.skillExitEventHandlers = (Player.SkillEventHandler)Delegate.Remove(player2.skillExitEventHandlers, new Player.SkillEventHandler(OnSkillExit));
30			if (givenStatus)
31			{
32				Player player3 = parentPlayer;
33				player3.skillEnterEventHandlers = (Player.SkillEventHandler)Delegate.Combine(player3.skillEnterEventHandlers, new Player.SkillEventHandler(OnSkillEnter));
34				Player player4 = parentPlayer;
35				player4.skillExitEventHandlers = (Player.SkillEventHandler)Delegate.Combine(player4.skillExitEventHandlers, new Player.SkillEventHandler(OnSkillExit));
36			}
37			return true;
38		}
39		public override void ApplyMods(bool givenStatus, int givenCount)
40		{
41			if (givenStatus)
42			{
43				evadeChance = 0.1f + 0.025f * (float)givenCount;
44				chanceMod.modValue = baseChance + incChance * (float)givenCount;
45			}
46		}
47		private void OnSkillEnter(Player.SkillState givenSkill)
48		{
49			if (givenSkill.isDash && givenSkill is Player.BaseDashState)
50			{
51				evadeApplied = UnityEngine.Random.value <= evadeChance;
52				if (evadeApplied)
53				{
54					parentPlayer.health.evadeStat.AddMod(evadeMod);
55					SetEffectStatus(givenStatus: true);
56				}
57				modApplied = UnityEngine.Random.value < chanceMod.modValue;
58				if (modApplied)
59				{
60					dashSkill = givenSkill as Player.BaseDashState;
61					dashSkill.disableStartCooldown = true;
62					dashSkill.cooldownReady = true;
63					PoolManager.GetPoolItem<ParticleEffect>("SparkleAura").Emit(7, parentPlayer.attackOriginTrans.position);
64					SoundManager.PlayAudioWithDistance("MagicianSparkle", parentPlayer.attackOriginTrans.position, null, 24f, -1f, 1.25f);
65				}
66			}
67		}
68		private void OnSkillExit(Player.SkillState givenSkill)
69		{
70			if (evadeApplied)
71			{
72				parentPlayer.health.evadeStat.RemoveMod(evadeMod);
73				SetEffectStatus(givenStatus: false);
74			}
75		}
76		private void SetEffectStatus(bool givenStatus)
77		{
78			if (givenStatus)
79			{
80				currentEffect = Globals.ChaosInst<ParticleEffect>(Player.UseWindDefense.EffectPrefab, null, parentPlayer.attackOriginTrans.position);
81				ParticleEffect particleEffect = currentEffect;
82				int? particleCount = 20;
83				ParticleSystemOverride evadeEffectOverride = Player.UseWindDefense.evadeEffectOverride;
84				particleEffect.Emit(particleCount, null, evadeEffectOverride);
85				currentEffect.followTransform = parentPlayer.attackOriginTrans;
86			}
87			else if (currentEffect != null)
88			{
89				if (currentEffect.gameObject != null)
90				{
91					UnityEngine.Object.Destroy(currentEffect.gameObject, 1f);
92				}
93				currentEffect = null;
94			}
95		}
96	}
