247		private void OnDoTEvent(AttackInfo givenAtkInfo, ElementType dotElement, Entity attackEntity = null, Entity hurtEntity = null)
248		{
249			if (cdStopwatch.IsRunning || parentPlayer == null || givenAtkInfo.skillCategory != parentPlayer.skillCategory || hurtEntity == null || hurtEntity.dotManager == null || givenAtkInfo.skillID.StartsWith(staticID) || givenAtkInfo.isStatusEffect || UnityEngine.Random.value > activationChance)
250			{
251				return;
252			}
253			cdStopwatch.IsRunning = true;
254			AttackInfo attackInfo = new AttackInfo();
255			attackInfo.skillCategory = parentPlayer.skillCategory;
256			attackInfo.skillID = staticID + dotElement;
257			attackInfo.damage = 0;
258			attackInfo.showDamageNumber = false;
259			attackInfo.shakeCamera = false;
260			attackInfo.canHitStun = false;
261			attackInfo.targetNames = givenAtkInfo.targetNames;
262			attackInfo.sameAttackImmunityTime = 0.25f;
263			attackInfo.entity = parentPlayer;
264			attackInfo.gameObject = parentPlayer.gameObject;
265			attackInfo.attackerPosition = givenAtkInfo.attackerPosition;
266			attackInfo.targetPosition = givenAtkInfo.targetPosition;
267			attackInfo.elementType = givenAtkInfo.elementType;
268			attackInfo.subElementType = givenAtkInfo.subElementType;
269			Vector2 vector = hurtEntity.hurtBoxTransform.position;
270			switch (dotElement)
271			{
272			case ElementType.Fire:
273				attackInfo.burnChance = 1f;
274				attackInfo.burnLevel = givenAtkInfo.burnLevel;
275				FlameBurst.CreateBurst(vector, attackInfo, burstRadius);
276				break;
277			case ElementType.Water:
278				if (!hurtEntity.fsm.currentStateName.Contains("Frozen"))
279				{
280					attackInfo.freezeChance = 1f;
281					attackInfo.freezeDuration = givenAtkInfo.freezeDuration;
282					IceBurst.CreateBurst(vector, attackInfo, burstRadius);
283				}
284				break;
285			case ElementType.Earth:
286				attackInfo.poisonChance = 1f;
287				attackInfo.poisonLevel = givenAtkInfo.poisonLevel;
288				currentPB = Globals.ChaosInst<PoisonBomb>(PoisonBomb.Prefab, null, vector);
289				currentPB.attackBox.SetAttackInfo(givenAtkInfo);
290				currentPB.targetPosition = vector;
291				currentPB.randomOffset = 0f;
292				currentPB.explosionDelay = 0f;
293				currentPB.poisonDuration = 0.5f;
294				currentPB.attackRadius = burstRadius;
295				currentPB.useCastingCircle = false;
296				currentPB.poisonType = PoisonType.Green;
297				currentPB.baseFlightTime = 0f;
298				break;
299			case ElementType.Air:
300				attackInfo.slowChance = 1f;
301				attackInfo.slowLevel = givenAtkInfo.slowLevel;
302				WindBurst.CreateBurst(vector, attackInfo, burstRadius);
303				break;
304			case ElementType.Lightning:
305				attackInfo.shockChance = 1f;
306				attackInfo.shockLevel = givenAtkInfo.shockLevel;
307				LightningBurst.CreateBurst(vector, attackInfo, burstRadius);
308				break;
309			}
310		}
311	}
